// ============================================================
// PTS3 Result - Client Script (Visual Inspection)
// DocType: PTS3 Result
// Renders: Summary, Step Sweep (chart + table), Mode (chart + table), Left/Right/Diff, Artifacts
// Uses final_graph_json, mode_values_json, left_right_diff_summary_json, artifact_paths
// ============================================================

(function () {
  /** F12 console: filter by [PTS3] */
  function pts3Dbg() {
    try {
      if (typeof console !== "undefined" && console.info) {
        var a = Array.prototype.slice.call(arguments);
        console.info.apply(console, ["[PTS3]"].concat(a));
      }
    } catch (e) {}
  }

  // Chart styling - theme-aware (light/dark mode compatible)
  var CHART = {
    width: 1000,
    height: 500,
    padding: { top: 20, right: 20, bottom: 40, left: 102 },
    fontSize: 10,        // Axis and label font size (e.g. 8, 10, 12)
    lineLeft: "#E53935",   // Red for Left
    lineRight: "#2196F3",  // Blue for Right
    lineDiff: "#4CAF50",   // Green for Diff
    barP1: "#E53935",      // Red for P1 (Left)
    barP2: "#2196F3",      // Blue for P2 (Right)
    barDiff: "#4CAF50",    // Green for Diff
    axisColor: "var(--text-muted, #6c7680)",
    gridColor: "var(--border-color, #d1d8dd)"
  };

  /**
   * Step Sweep + Diff vs Hz share font, grid/axis widths, tick size, xTickHz.
   * yTickStep: Diff vs Hz Y grid step. yTickStepSweep: Step Sweep Y grid step (e.g. 250).
   * yAxisTitleSweep / yAxisTitleDiff: Y-axis label ("" to hide).
   * gridOpacity / gridStrokeWidth: major grid lines (both Step Sweep + Diff vs Hz).
   * yAxisTitleGapPx: horizontal space from plot Y-axis to rotated title (larger = title further left).
   */
  var PTS3_SHARED_AXIS = {
    fontSize: 20,
    yAxisTitleGapPx: 96,
    gridStrokeWidth: 2,
    gridOpacity: 1,
    axisStrokeWidth: 1,
    tickLength: 4,
    xTickHz: 2,
    yTickStep: 40,
    yTickStepSweep: 250,
    maxYTicks: 16,
    yAxisTitleSweep: "Voltage in mV",
    yAxisTitleDiff: "Difference"
  };

  // Step Sweep Y-axis: both yMin and yMax set => fixed range (Left/Right scale; Diff is clipped in plot).
  // One or both null => auto from Left+Right only (Diff does not shrink the axis).
  var SWEEP_CHART = {
    yMin: 1500,
    yMax: 4000,
    lineWidth: 2,
    diffLineWidth: 1.5,
    fontSize: null
  };

  // Mode bar chart + Diff vs frequency (Hz) line chart share these Y limits when set.
  // Both yMin and yMax set => fixed axis for those charts (no auto expand). One or both null => auto from data where needed.
  var MODE_CHART = {
    yMin: -120,
    yMax: 120,
    fontSize: null
  };

  /**
   * Mode Results horizontal bar chart only (X = value). Does not affect Diff vs Hz (uses MODE_CHART.yMin/yMax).
   * plotWidth: SVG viewBox width (larger = wider graph). rowBand / innerGap: thicker bars when rowBand ↑ or innerGap ↓.
   */
  var MODE_HBAR = {
    valueMin: 0,
    valueMax: 3500,
    tickStep: 250,
    plotWidth: 1280,
    rowBand: 78,
    innerGap: 3,
    labelColW: 108,
    xTickFontShrink: 5,
    /** Left / Right / Difference row only (px). Set null to match chart axis font (pts3_axis_font / MODE_CHART.fontSize). */
    legendFontPx: 12
  };

  /** Sans stack for mode SVG text (matches legend; single-quoted names safe inside style="..."). */
  var PTS3_SANS_FONT_STACK_CSS = "system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif";

  // Key/Left/Right/Diff vertical table from left_right_diff_summary_json (duplicate of Step Sweep channel table).
  // Set true to show it again under result_inspection HTML.
  var SHOW_LEFT_RIGHT_DIFF_SUMMARY_SECTION = false;

  // Match Desk user menu "Toggle Full Width" (uses localStorage + body.full-width). Set false to leave desk width unchanged.
  var PTS3_ENABLE_DESK_FULL_WIDTH_ON_LOAD = true;

  var HTML2CANVAS_CDN = "https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js";
  var INSPECTION_PNG_SCALE = 2.5;

  if (document.getElementById("pts3-result-style-v9") == null) {
    ["pts3-result-style", "pts3-result-style-v4", "pts3-result-style-v5", "pts3-result-style-v6", "pts3-result-style-v7", "pts3-result-style-v8"].forEach(function (rid) {
      var old = document.getElementById(rid);
      if (old && old.parentNode) {
        old.parentNode.removeChild(old);
      }
    });
    var style = document.createElement("style");
    style.id = "pts3-result-style-v9";
    style.textContent =
      ".pts3-result-table td.pts3-diff-ok,.pts3-mode-step-table td.pts3-diff-ok{background:#d4edda!important;color:#1b5e20!important;font-weight:500;}.pts3-inspection-capture-root{width:100%;max-width:100%;box-sizing:border-box;margin:0;display:block;}.pts3-inspection-capture-body{width:100%;max-width:100%;box-sizing:border-box;position:relative;}.pts3-summary-mode-row{display:flex;flex-wrap:wrap;gap:1rem;align-items:stretch;width:100%;box-sizing:border-box;}.pts3-summary-mode-row>.pts3-result-section{flex:1 1 360px;min-width:min(100%,240px);margin:1rem 0;box-sizing:border-box;}.pts3-result-section{margin:1rem 0;padding:0.75rem;border:1px solid var(--border-color,#d1d8dd);border-radius:4px;}.pts3-result-section h4{margin:0 0 0.5rem 0;font-size:1rem;color:var(--text-color,#36414c);}.pts3-result-table{width:100%;max-width:100%;border-collapse:collapse;font-size:0.85em;}.pts3-result-table th,.pts3-result-table td{border:1px solid var(--border-color,#d1d8dd);padding:4px 8px;text-align:left;color:var(--text-color,#36414c);}.pts3-result-table th{background:var(--control-bg,#f5f7fa);}.pts3-result-artifact{margin:0.25rem 0;font-size:0.9em;}.pts3-result-no-data{color:var(--text-muted,#8d99a6);font-style:italic;}.pts3-result-pass{color:#27ae60;}.pts3-result-fail{color:#e74c3c;}.pts3-chart-wrap{margin:0.5rem 0;overflow:hidden;width:100%;max-width:100%;min-width:0;box-sizing:border-box;}.pts3-chart-wrap svg.pts3-chart-svg,.pts3-sweep-chart-container svg.pts3-chart-svg{display:block;width:100%;max-width:100%;height:auto;vertical-align:top;}.pts3-sweep-diff-row{display:flex;flex-wrap:wrap;gap:1rem;align-items:flex-start;margin:0.5rem 0;width:100%;max-width:100%;box-sizing:border-box;}.pts3-sweep-diff-col{flex:1 1 420px;min-width:min(100%,320px);box-sizing:border-box;}.pts3-sweep-diff-col .pts3-chart-wrap{margin:0;}.pts3-mode-layout{display:flex;flex-wrap:wrap;gap:1rem;align-items:stretch;}.pts3-mode-legend{width:100%;margin-bottom:0.25rem;font-family:system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif;}.pts3-mode-chart{flex:1 1 720px;min-width:min(100%,520px);}.pts3-mode-chart-only{flex:1 1 100%;min-width:0;}.pts3-sweep-chart-container{position:relative;display:block;cursor:crosshair;min-width:0;min-height:260px;width:100%;max-width:100%;}.pts3-sweep-tooltip{position:absolute;display:none;background:var(--gray-900,#36414c);color:var(--gray-100,#fff);padding:6px 10px;border-radius:4px;font-size:11px;font-family:monospace;white-space:nowrap;pointer-events:none;z-index:1000;box-shadow:0 2px 8px rgba(0,0,0,0.2);}.pts3-sweep-tooltip.visible{display:block;}.pts3-inspection-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:0.65rem;padding-bottom:0.5rem;border-bottom:1px solid var(--border-color,#d1d8dd);}.pts3-mode-under-step{margin-top:1rem;padding-top:0.85rem;border-top:1px solid var(--border-color,#e2e8f0);}.pts3-mode-under-step-title{margin:0 0 0.5rem 0;font-size:0.95rem;font-weight:600;color:var(--text-color,#36414c);}.pts3-mode-step-table{font-size:0.9em;}.pts3-mode-step-table thead th{background:#f8f9fa!important;font-weight:700;color:#212529;border:1px solid #dee2e6!important;padding:8px 10px;}.pts3-mode-step-table tbody td{border:1px solid #dee2e6!important;padding:8px 10px;background:#fff;color:#212529;}.pts3-mode-step-table tbody td.pts3-mode-step-name{color:#1976d2;font-weight:500;}";
    document.head.appendChild(style);
  }

  /** Accepts JSON string or already-parsed object (some Frappe/API paths deserialize Code fields). */
  function safe_json(val, fallback) {
    if (val == null || val === "") return fallback || {};
    if (typeof val === "object" && val !== null && !Array.isArray(val)) {
      return val;
    }
    if (typeof val === "string") {
      try {
        var o = JSON.parse(val);
        return o && typeof o === "object" && !Array.isArray(o) ? o : (fallback || {});
      } catch (e) {
        return fallback || {};
      }
    }
    return fallback || {};
  }

  function escape_html(s) {
    if (s == null || s === undefined) return "";
    var t = String(s);
    return t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function render_summary(frm) {
    var d = frm.doc;
    var html = '<div class="pts3-result-section"><h4>Summary</h4><table class="pts3-result-table"><tbody>';
    html += "<tr><th>PCB Serial No</th><td>" + escape_html(d.pcb_serial_no || "") + "</td></tr>";
    html += "<tr><th>Run ID</th><td>" + escape_html(d.run_id || "") + "</td></tr>";
    html += "<tr><th>Operation</th><td>" + escape_html(d.operation || "") + "</td></tr>";
    html += "<tr><th>Datetime</th><td>" + escape_html(d.datetime || "") + "</td></tr>";
    var pf = (d.pass_fail || "").trim();
    var pfClass = pf === "Pass" ? "pts3-result-pass" : pf === "Fail" ? "pts3-result-fail" : "";
    html += "<tr><th>Pass/Fail</th><td class=\"" + pfClass + "\">" + escape_html(pf || "-") + "</td></tr>";
    html += "<tr><th>Dominant Channel</th><td>" + escape_html(d.dominant_channel || "") + "</td></tr>";
    html += "<tr><th>Max Value</th><td>" + escape_html(d.max_value != null ? d.max_value : "") + "</td></tr>";
    html += "</tbody></table></div>";
    return html;
  }

  function format_num(v) {
    if (v == null || isNaN(v)) return "";
    var n = Number(v);
    return n % 1 === 0 ? String(n) : n.toFixed(2);
  }

  /** HTML tables: green Difference/Diff cell when |value| <= this (edit to change tolerance). */
  var PTS3_DIFF_OK_ABS_MAX = 40;

  function pts3_is_diff_within_tolerance(v) {
    if (v == null || v === "") return false;
    var n = Number(v);
    if (isNaN(n)) return false;
    return Math.abs(n) <= PTS3_DIFF_OK_ABS_MAX;
  }

  function pts3_diff_td_open(v) {
    return pts3_is_diff_within_tolerance(v) ? '<td class="pts3-diff-ok">' : "<td>";
  }

  function pts3_axis_font() {
    if (SWEEP_CHART.fontSize != null) {
      return SWEEP_CHART.fontSize;
    }
    return PTS3_SHARED_AXIS.fontSize != null ? PTS3_SHARED_AXIS.fontSize : (CHART.fontSize || 10);
  }

  function pts3_x_tick_hz() {
    return PTS3_SHARED_AXIS.xTickHz > 0 ? PTS3_SHARED_AXIS.xTickHz : 2;
  }

  function pts3_y_step_for_range(vMin, vMax, baseStep) {
    var step;
    if (baseStep != null && baseStep > 0) {
      step = baseStep;
    } else {
      step = PTS3_SHARED_AXIS.yTickStep > 0 ? PTS3_SHARED_AXIS.yTickStep : 40;
    }
    var span = Math.max(vMax - vMin, 1e-9);
    var maxT = PTS3_SHARED_AXIS.maxYTicks > 0 ? PTS3_SHARED_AXIS.maxYTicks : 16;
    while (span / step > maxT) {
      step *= 2;
    }
    return step;
  }

  function pts3_snap_bounds(vMin, vMax, step) {
    var lo = Math.floor(vMin / step) * step;
    var hi = Math.ceil(vMax / step) * step;
    if (hi <= lo) {
      hi = lo + step;
    }
    return { min: lo, max: hi };
  }

  function pts3_grid_line_style(gridClr) {
    var gsw = PTS3_SHARED_AXIS.gridStrokeWidth > 0 ? PTS3_SHARED_AXIS.gridStrokeWidth : 1;
    var go = PTS3_SHARED_AXIS.gridOpacity != null ? PTS3_SHARED_AXIS.gridOpacity : 0.72;
    return (
      ' stroke="' +
      gridClr +
      '" stroke-width="' +
      gsw +
      '" stroke-opacity="' +
      go +
      '" shape-rendering="crispEdges"'
    );
  }

  function pts3_append_x_grid(svg, gx, gy, gw, gh, labelY, freqMin, freqMax, axisClr, gridClr, fs) {
    var freqRange = freqMax - freqMin || 1;
    var xHz = pts3_x_tick_hz();
    var tickLen = PTS3_SHARED_AXIS.tickLength;
    var asw = PTS3_SHARED_AXIS.axisStrokeWidth;
    function xFromFreq(f) {
      return gx + ((Number(f) - freqMin) / freqRange) * gw;
    }
    for (var tickFreq = freqMin; tickFreq <= freqMax + 1e-9; tickFreq += xHz) {
      var xx = xFromFreq(tickFreq);
      if (xx < gx - 1 || xx > gx + gw + 1) {
        continue;
      }
      svg += '<line x1="' + xx + '" y1="' + (gy + gh) + '" x2="' + xx + '" y2="' + gy + '"' + pts3_grid_line_style(gridClr) + "/>";
      if (tickFreq > freqMin && tickFreq < freqMax) {
        svg += '<line x1="' + xx + '" y1="' + (gy + gh) + '" x2="' + xx + '" y2="' + (gy + gh + tickLen) + '" stroke="' + axisClr + '" stroke-width="' + asw + '"/>';
      }
      svg += '<text x="' + xx + '" y="' + labelY + '" text-anchor="middle" font-size="' + fs + '" fill="' + axisClr + '">' + tickFreq + "</text>";
    }
    return svg;
  }

  function pts3_append_y_grid(svg, gx, gy, gw, gh, vMin, vMax, yStep, axisClr, gridClr, fs) {
    var vRange = vMax - vMin || 1;
    var tickLen = PTS3_SHARED_AXIS.tickLength;
    var asw = PTS3_SHARED_AXIS.axisStrokeWidth;
    var startTick = Math.floor(vMin / yStep + 1e-12) * yStep;
    for (var tv = startTick; tv <= vMax + 1e-9; tv += yStep) {
      if (tv < vMin - 1e-9) {
        continue;
      }
      var yy = gy + gh - ((tv - vMin) / vRange) * gh;
      svg += '<line x1="' + gx + '" y1="' + yy + '" x2="' + (gx + gw) + '" y2="' + yy + '"' + pts3_grid_line_style(gridClr) + "/>";
      svg += '<line x1="' + (gx - tickLen) + '" y1="' + yy + '" x2="' + gx + '" y2="' + yy + '" stroke="' + axisClr + '" stroke-width="' + asw + '"/>';
      svg += '<text x="' + (gx - 6) + '" y="' + (yy + 3) + '" text-anchor="end" font-size="' + fs + '" fill="' + axisClr + '">' + format_num(tv) + "</text>";
    }
    return svg;
  }

  function pts3_append_y_axis_title(svg, titleText, gx, gy, gh, axisClr, fs) {
    if (titleText == null || String(titleText).trim() === "") {
      return svg;
    }
    var mid = gy + gh / 2;
    var titleGap = PTS3_SHARED_AXIS.yAxisTitleGapPx != null ? PTS3_SHARED_AXIS.yAxisTitleGapPx : 96;
    var lx = Math.max(12, gx - titleGap);
    svg +=
      '<text transform="translate(' +
      lx +
      "," +
      mid +
      ') rotate(-90)" text-anchor="middle" dominant-baseline="middle" font-size="' +
      fs +
      '" fill="' +
      axisClr +
      '">' +
      escape_html(String(titleText).trim()) +
      "</text>";
    return svg;
  }

  function render_sweep_chart_svg(freqs, left, right, diff) {
    if (!freqs || freqs.length < 2) return { svg: "", coords: null };
    var pw = CHART.width;
    var ph = CHART.height;
    var pad = CHART.padding;
    var gx = pad.left;
    var gy = pad.top;
    var gw = pw - pad.left - pad.right;
    var gh = ph - pad.top - pad.bottom;
    var axisClr = CHART.axisColor;
    var gridClr = CHART.gridColor;
    var fs = pts3_axis_font();
    var asw = PTS3_SHARED_AXIS.axisStrokeWidth;

    var lrVals = [];
    for (var i = 0; i < left.length; i++) {
      if (left[i] != null) lrVals.push(Number(left[i]));
    }
    for (var j = 0; j < right.length; j++) {
      if (right[j] != null) lrVals.push(Number(right[j]));
    }
    var lrMin = lrVals.length ? Math.min.apply(null, lrVals) : 0;
    var lrMax = lrVals.length ? Math.max.apply(null, lrVals) : 1;
    var yminC = SWEEP_CHART.yMin;
    var ymaxC = SWEEP_CHART.yMax;
    var vMin;
    var vMax;
    var sweepSnap;
    if (yminC != null && ymaxC != null) {
      vMin = Number(yminC);
      vMax = Number(ymaxC);
      sweepSnap = false;
    } else if (yminC == null && ymaxC == null) {
      vMin = lrMin;
      vMax = lrMax;
      sweepSnap = true;
    } else if (yminC != null) {
      vMin = Number(yminC);
      vMax = ymaxC != null ? Number(ymaxC) : lrMax;
      if (ymaxC == null) {
        vMax = Math.max(vMax, lrMax);
      }
      sweepSnap = true;
    } else {
      vMin = lrMin;
      vMax = Number(ymaxC);
      vMax = Math.max(vMax, lrMax);
      sweepSnap = true;
    }
    var sweepStepBase = PTS3_SHARED_AXIS.yTickStepSweep > 0 ? PTS3_SHARED_AXIS.yTickStepSweep : PTS3_SHARED_AXIS.yTickStep;
    var yStep = pts3_y_step_for_range(vMin, vMax, sweepStepBase);
    if (sweepSnap) {
      var snapped = pts3_snap_bounds(vMin, vMax, yStep);
      vMin = snapped.min;
      vMax = snapped.max;
    }
    var vRange = vMax - vMin || 1;

    function x(i) {
      return gx + (i / Math.max(freqs.length - 1, 1)) * gw;
    }
    function y(v) {
      return gy + gh - ((Number(v) - vMin) / vRange) * gh;
    }

    function path(arr) {
      var pts = [];
      for (var ii = 0; ii < arr.length; ii++) {
        if (arr[ii] != null && !isNaN(Number(arr[ii]))) {
          pts.push(x(ii) + "," + y(arr[ii]));
        }
      }
      return pts.length ? "M" + pts.join(" L") : "";
    }

    var pLeft = path(left);
    var pRight = path(right);
    var pDiff = path(diff);

    var freqMin = Number(freqs[0]) || 0;
    var freqMax = Number(freqs[freqs.length - 1]) || 1;
    var freqRange = freqMax - freqMin || 1;

    var clipId = "pts3_sw_" + String(Date.now()) + "_" + String(Math.floor(Math.random() * 1e9));
    var svg =
      '<svg class="pts3-chart-svg" width="' +
      pw +
      '" height="' +
      ph +
      '" viewBox="0 0 ' +
      pw +
      " " +
      ph +
      '" preserveAspectRatio="xMidYMid meet" style="max-width:100%;height:auto;display:block;">' +
      "<defs><clipPath id=\"" +
      clipId +
      '"><rect x="' +
      gx +
      '" y="' +
      gy +
      '" width="' +
      gw +
      '" height="' +
      gh +
      '"/></clipPath></defs><g>';
    svg = pts3_append_x_grid(svg, gx, gy, gw, gh, ph - 2, freqMin, freqMax, axisClr, gridClr, fs);
    svg = pts3_append_y_grid(svg, gx, gy, gw, gh, vMin, vMax, yStep, axisClr, gridClr, fs);
    svg = pts3_append_y_axis_title(svg, PTS3_SHARED_AXIS.yAxisTitleSweep, gx, gy, gh, axisClr, fs);
    svg += '<line x1="' + gx + '" y1="' + (gy + gh) + '" x2="' + (gx + gw) + '" y2="' + (gy + gh) + '" stroke="' + axisClr + '" stroke-width="' + asw + '"/>';
    svg += '<line x1="' + gx + '" y1="' + gy + '" x2="' + gx + '" y2="' + (gy + gh) + '" stroke="' + axisClr + '" stroke-width="' + asw + '"/>';
    var lw = SWEEP_CHART.lineWidth > 0 ? SWEEP_CHART.lineWidth : 2;
    var dlw = SWEEP_CHART.diffLineWidth != null ? SWEEP_CHART.diffLineWidth : lw;
    svg += '<g clip-path="url(#' + clipId + ')">';
    if (pLeft) svg += '<path d="' + pLeft + '" fill="none" stroke="' + CHART.lineLeft + '" stroke-width="' + lw + '"/>';
    if (pRight) svg += '<path d="' + pRight + '" fill="none" stroke="' + CHART.lineRight + '" stroke-width="' + lw + '"/>';
    if (pDiff) svg += '<path d="' + pDiff + '" fill="none" stroke="' + CHART.lineDiff + '" stroke-width="' + dlw + '" stroke-dasharray="4,2"/>';
    svg += "</g></g></svg>";
    var coords = { freqMin: freqMin, freqMax: freqMax, freqRange: freqRange, vMin: vMin, vMax: vMax, vRange: vRange, gx: gx, gy: gy, gw: gw, gh: gh, pw: pw, ph: ph };
    return { svg: svg, coords: coords };
  }

  /** Line chart: Diff (Y) vs index-aligned Hz (X). Y-scale uses diff values only. */
  function render_diff_vs_hz_svg(freqs, diff) {
    if (!freqs || freqs.length < 2 || !diff || diff.length < 2) {
      return "";
    }
    var diffs = [];
    for (var i = 0; i < diff.length; i++) {
      if (diff[i] != null && !isNaN(Number(diff[i]))) {
        diffs.push(Number(diff[i]));
      }
    }
    if (diffs.length < 2) {
      return "";
    }

    var pw = CHART.width;
    var ph = CHART.height;
    var pad = CHART.padding;
    var gx = pad.left;
    var gy = pad.top;
    var gw = pw - pad.left - pad.right;
    var gh = ph - pad.top - pad.bottom;
    var axisClr = CHART.axisColor;
    var gridClr = CHART.gridColor;
    var fs = pts3_axis_font();
    var asw = PTS3_SHARED_AXIS.axisStrokeWidth;

    var rawMin = Math.min.apply(null, diffs);
    var rawMax = Math.max.apply(null, diffs);
    var span = rawMax - rawMin;
    var padY = span > 0 ? span * 0.1 : Math.max(Math.abs(rawMin), Math.abs(rawMax), 1) * 0.1;
    var dymin = MODE_CHART.yMin;
    var dymax = MODE_CHART.yMax;
    var vMin;
    var vMax;
    var diffSnap;
    if (dymin != null && dymax != null) {
      vMin = Number(dymin);
      vMax = Number(dymax);
      diffSnap = false;
    } else if (dymin == null && dymax == null) {
      vMin = rawMin - padY;
      vMax = rawMax + padY;
      if (vMin === vMax) {
        vMin -= 1;
        vMax += 1;
      }
      diffSnap = true;
    } else if (dymin != null) {
      vMin = Number(dymin);
      vMax = dymax != null ? Number(dymax) : rawMax + padY;
      if (dymax == null) {
        vMax = Math.max(vMax, rawMax + padY);
      }
      diffSnap = true;
    } else {
      vMax = Math.max(Number(dymax), rawMax + padY);
      vMin = rawMin - padY;
      if (vMin >= vMax) {
        vMin = vMax - 1;
      }
      diffSnap = true;
    }
    var yStep = pts3_y_step_for_range(vMin, vMax);
    if (diffSnap) {
      var snappedD = pts3_snap_bounds(vMin, vMax, yStep);
      vMin = snappedD.min;
      vMax = snappedD.max;
    }
    var vRange = vMax - vMin || 1;

    var freqMin = Number(freqs[0]) || 0;
    var freqMax = Number(freqs[freqs.length - 1]) || 1;

    function x(i) {
      return gx + (i / Math.max(freqs.length - 1, 1)) * gw;
    }
    function y(v) {
      return gy + gh - ((Number(v) - vMin) / vRange) * gh;
    }

    var pts = [];
    for (var pi = 0; pi < diff.length; pi++) {
      if (diff[pi] != null && !isNaN(Number(diff[pi]))) {
        pts.push(x(pi) + "," + y(diff[pi]));
      }
    }
    var pathD = pts.length ? "M" + pts.join(" L") : "";

    var svg = '<svg class="pts3-chart-svg pts3-diff-hz-chart" width="' + pw + '" height="' + ph + '" viewBox="0 0 ' + pw + " " + ph + '" preserveAspectRatio="xMidYMid meet" style="max-width:100%;height:auto;display:block;"><g>';
    svg = pts3_append_x_grid(svg, gx, gy, gw, gh, ph - 2, freqMin, freqMax, axisClr, gridClr, fs);
    svg = pts3_append_y_grid(svg, gx, gy, gw, gh, vMin, vMax, yStep, axisClr, gridClr, fs);
    svg = pts3_append_y_axis_title(svg, PTS3_SHARED_AXIS.yAxisTitleDiff, gx, gy, gh, axisClr, fs);

    if (vMin <= 0 && vMax >= 0) {
      var y0 = y(0);
      if (y0 >= gy && y0 <= gy + gh) {
        svg += '<line x1="' + gx + '" y1="' + y0 + '" x2="' + (gx + gw) + '" y2="' + y0 + '" stroke="' + axisClr + '" stroke-width="' + asw + '" stroke-dasharray="3,3" opacity="0.7"/>';
      }
    }

    svg += '<line x1="' + gx + '" y1="' + (gy + gh) + '" x2="' + (gx + gw) + '" y2="' + (gy + gh) + '" stroke="' + axisClr + '" stroke-width="' + asw + '"/>';
    svg += '<line x1="' + gx + '" y1="' + gy + '" x2="' + gx + '" y2="' + (gy + gh) + '" stroke="' + axisClr + '" stroke-width="' + asw + '"/>';

    var lw = SWEEP_CHART.lineWidth > 0 ? SWEEP_CHART.lineWidth : 2;
    if (pathD) {
      svg += '<path d="' + pathD + '" fill="none" stroke="' + CHART.lineDiff + '" stroke-width="' + lw + '"/>';
    }

    svg += "</g></svg>";
    return svg;
  }

  function build_sweep_from_lrd(t) {
    if (!t || typeof t !== "object") return null;
    var left = t.left || {};
    var right = t.right || {};
    var diff = t.diff || {};
    var keys = Object.keys(left).concat(Object.keys(right)).concat(Object.keys(diff));
    keys = keys.filter(function (k, i, a) { return a.indexOf(k) === i; }).sort(function (a, b) {
      var na = parseInt(String(a).replace(/[^0-9]/g, ""), 10) || 0;
      var nb = parseInt(String(b).replace(/[^0-9]/g, ""), 10) || 0;
      return na - nb;
    });
    if (keys.length < 2) return null;
    var freqs = [];
    var leftArr = [];
    var rightArr = [];
    var diffArr = [];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      var hz = parseInt(String(k).replace(/[^0-9]/g, ""), 10);
      if (!isNaN(hz)) {
        freqs.push(hz);
        leftArr.push(left[k] != null ? left[k] : null);
        rightArr.push(right[k] != null ? right[k] : null);
        diffArr.push(diff[k] != null ? diff[k] : null);
      }
    }
    return freqs.length >= 2 ? { freqs: freqs, left: leftArr, right: rightArr, diff: diffArr } : null;
  }

  /** Mode L/R/Diff table for placement under the Step Sweep frequency table (uses mode_values_json). */
  function render_mode_table_under_step(frm) {
    var m = safe_json(frm.doc.mode_values_json, null);
    if (!m || typeof m !== "object") return "";
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var body = "";
    var any = false;
    for (var i = 0; i < order.length; i++) {
      var k = order[i];
      var v = get_mode_value(m, k);
      if (v && typeof v === "object") {
        any = true;
        body +=
          "<tr><td class=\"pts3-mode-step-name\">" +
          escape_html(k) +
          "</td><td>" +
          escape_html(v.p1 != null ? format_num(v.p1) : "") +
          "</td><td>" +
          escape_html(v.p2 != null ? format_num(v.p2) : "") +
          "</td>" +
          pts3_diff_td_open(v.diff) +
          escape_html(v.diff != null ? format_num(v.diff) : "") +
          "</td></tr>";
      }
    }
    if (!any) return "";
    return (
      '<div class="pts3-mode-under-step">' +
      '<p class="pts3-mode-under-step-title">Mode</p>' +
      '<table class="pts3-result-table pts3-mode-step-table"><thead><tr><th>Mode</th><th>Left</th><th>Right</th><th>Difference</th></tr></thead><tbody>' +
      body +
      "</tbody></table></div>"
    );
  }

  function render_step_sweep(frm) {
    var g = safe_json(frm.doc.final_graph_json, null);
    var isSweep = g && (g.type === "sweep" || g.type === "step_sweep") && (g.freqs || []).length >= 2;
    if (!isSweep) {
      var lrd = safe_json(frm.doc.left_right_diff_summary_json, null);
      g = build_sweep_from_lrd(lrd);
    }
    if (!g || !g.freqs || g.freqs.length < 2) {
      return '<div class="pts3-result-section"><h4>Step Sweep</h4><p class="pts3-result-no-data">No sweep data</p></div>';
    }
    var freqs = g.freqs || [];
    var left = g.left || [];
    var right = g.right || [];
    var diff = g.diff || [];
    var html = '<div class="pts3-result-section"><h4>Step Sweep</h4>';
    if (freqs.length >= 2) {
      var sweepFs = pts3_axis_font();
      var sweepAxis = CHART.axisColor;
      var chartResult = render_sweep_chart_svg(freqs, left, right, diff);
      var sweepData = JSON.stringify({ freqs: freqs, left: left, right: right, diff: diff, coords: chartResult.coords });
      var diffHzSvg = render_diff_vs_hz_svg(freqs, diff);
      var sweepLegend = '<p style="font-size:' + sweepFs + 'px;margin:0 0 4px 0;"><span style="color:' + CHART.lineLeft + '">—</span> Left &nbsp; <span style="color:' + CHART.lineRight + '">—</span> Right &nbsp; <span style="color:' + CHART.lineDiff + '">- -</span> Diff</p>';
      var sweepBlock = sweepLegend + '<div class="pts3-sweep-chart-container" data-sweep="' + escape_html(sweepData) + '"><div class="pts3-sweep-tooltip" id="pts3-sweep-tooltip"></div>' + chartResult.svg + "</div>";
      if (diffHzSvg) {
        html += '<div class="pts3-sweep-diff-row">';
        html += '<div class="pts3-sweep-diff-col"><div class="pts3-chart-wrap">' + sweepBlock + "</div></div>";
        html += '<div class="pts3-sweep-diff-col"><div class="pts3-chart-wrap pts3-diff-hz-wrap"><p style="font-size:' + sweepFs + 'px;margin:0 0 4px 0;color:' + sweepAxis + ';">Diff vs frequency (Hz)</p>' + diffHzSvg + "</div></div>";
        html += "</div>";
      } else {
        html += '<div class="pts3-chart-wrap">' + sweepBlock + "</div>";
      }
    }
    html += '<table class="pts3-result-table"><thead><tr><th>Channel</th>';
    for (var h = 0; h < freqs.length; h++) {
      html += '<th>' + escape_html(freqs[h]) + 'hz</th>';
    }
    html += '</tr></thead><tbody>';
    html += '<tr><td>Left</td>';
    for (var a = 0; a < freqs.length; a++) {
      html += '<td>' + escape_html(format_num(left[a])) + '</td>';
    }
    html += '</tr><tr><td>Right</td>';
    for (var b = 0; b < freqs.length; b++) {
      html += '<td>' + escape_html(format_num(right[b])) + '</td>';
    }
    html += '</tr><tr><td>Diff</td>';
    for (var c = 0; c < freqs.length; c++) {
      html += pts3_diff_td_open(diff[c]) + escape_html(format_num(diff[c])) + "</td>";
    }
    html += '</tr></tbody></table>';
    html += render_mode_table_under_step(frm);
    html += "</div>";
    return html;
  }

  function get_mode_value(m, key) {
    if (m[key]) return m[key];
    var lower = key.toLowerCase();
    if (m[lower]) return m[lower];
    return null;
  }

  function render_mode_chart_svg(modeData) {
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var rows = [];
    for (var i = 0; i < order.length; i++) {
      var v = get_mode_value(modeData, order[i]);
      if (v && typeof v === "object") {
        rows.push({
          label: order[i],
          left: v.p1 != null ? Number(v.p1) : 0,
          right: v.p2 != null ? Number(v.p2) : 0,
          diff: v.diff != null ? Number(v.diff) : 0
        });
      }
    }
    if (rows.length === 0) return "";

    var pw = MODE_HBAR.plotWidth > 0 ? MODE_HBAR.plotWidth : CHART.width;
    var rowBand = MODE_HBAR.rowBand > 0 ? MODE_HBAR.rowBand : 56;
    var innerGapCfg = MODE_HBAR.innerGap != null ? MODE_HBAR.innerGap : 4;
    var pad = { top: 38, right: 32, bottom: 58, left: 14 };
    var labelColW = MODE_HBAR.labelColW > 0 ? MODE_HBAR.labelColW : 100;
    var ph = pad.top + pad.bottom + rows.length * rowBand;

    var plotLeft = pad.left + labelColW;
    var plotRight = pw - pad.right;
    var plotW = Math.max(plotRight - plotLeft, 1);
    var plotTop = pad.top;
    var plotBottom = ph - pad.bottom;
    var plotH = plotBottom - plotTop;

    var minVal;
    var maxVal;
    if (MODE_HBAR.valueMin != null && MODE_HBAR.valueMax != null) {
      minVal = Number(MODE_HBAR.valueMin);
      maxVal = Number(MODE_HBAR.valueMax);
    } else {
      minVal = Infinity;
      maxVal = -Infinity;
      for (var r0 = 0; r0 < rows.length; r0++) {
        minVal = Math.min(minVal, rows[r0].left, rows[r0].right, rows[r0].diff);
        maxVal = Math.max(maxVal, rows[r0].left, rows[r0].right, rows[r0].diff);
      }
      if (!isFinite(minVal) || !isFinite(maxVal)) {
        minVal = 0;
        maxVal = 1;
      }
      if (minVal === maxVal) {
        minVal -= 1;
        maxVal += 1;
      }
    }
    if (!isFinite(minVal) || !isFinite(maxVal) || minVal >= maxVal) {
      minVal = 0;
      maxVal = 3500;
    }
    var valRange = Math.max(maxVal - minVal, 1e-9);

    function xAt(val) {
      return plotLeft + ((Number(val) - minVal) / valRange) * plotW;
    }

    function hBarGeom(val) {
      var baseVal = minVal < 0 && maxVal > 0 ? 0 : minVal;
      var xb = xAt(baseVal);
      var xv = xAt(val);
      xb = Math.max(plotLeft, Math.min(plotRight, xb));
      xv = Math.max(plotLeft, Math.min(plotRight, xv));
      var bx = Math.min(xb, xv);
      var bw = Math.max(Math.abs(xv - xb), 1);
      if (bx + bw > plotRight) {
        bw = plotRight - bx;
      }
      return { x: bx, w: Math.max(bw, 0.75) };
    }

    var axisClr = CHART.axisColor;
    var gridClr = CHART.gridColor;
    var fs = MODE_CHART.fontSize != null ? MODE_CHART.fontSize : pts3_axis_font();
    var fsSmall = Math.max(6, fs - 2);
    var barStroke = "rgba(0,0,0,0.35)";
    var svgFontStyle =
      "max-width:100%;height:auto;display:block;font-family:" + PTS3_SANS_FONT_STACK_CSS + ";";
    var svg =
      '<svg class="pts3-chart-svg pts3-mode-bar-chart pts3-mode-hbar-chart" viewBox="0 0 ' +
      pw +
      " " +
      ph +
      '" preserveAspectRatio="xMidYMid meet" style="' +
      svgFontStyle +
      '"><g>';

    var tickStep = MODE_HBAR.tickStep > 0 ? MODE_HBAR.tickStep : 250;
    var xfs = Math.max(7, fs - (MODE_HBAR.xTickFontShrink > 0 ? MODE_HBAR.xTickFontShrink : 5));
    for (var xVal = minVal; xVal <= maxVal + tickStep * 1e-6; xVal += tickStep) {
      var xx = xAt(xVal);
      svg +=
        '<line x1="' +
        xx +
        '" y1="' +
        plotTop +
        '" x2="' +
        xx +
        '" y2="' +
        plotBottom +
        '" stroke="' +
        gridClr +
        '" stroke-width="0.5" stroke-opacity="0.45" shape-rendering="crispEdges"/>';
      svg +=
        '<text x="' +
        xx +
        '" y="' +
        (ph - 12) +
        '" text-anchor="middle" font-size="' +
        xfs +
        '" fill="' +
        axisClr +
        '">' +
        format_num(xVal) +
        "</text>";
    }

    if (minVal < 0 && maxVal > 0) {
      var xz = xAt(0);
      if (xz >= plotLeft && xz <= plotRight) {
        svg +=
          '<line x1="' +
          xz +
          '" y1="' +
          plotTop +
          '" x2="' +
          xz +
          '" y2="' +
          plotBottom +
          '" stroke="' +
          axisClr +
          '" stroke-width="1" stroke-dasharray="4,3" opacity="0.85"/>';
      }
    }

    svg +=
      '<line x1="' +
      plotLeft +
      '" y1="' +
      plotBottom +
      '" x2="' +
      plotRight +
      '" y2="' +
      plotBottom +
      '" stroke="' +
      axisClr +
      '" stroke-width="1"/>';
    svg +=
      '<line x1="' +
      plotLeft +
      '" y1="' +
      plotTop +
      '" x2="' +
      plotLeft +
      '" y2="' +
      plotBottom +
      '" stroke="' +
      axisClr +
      '" stroke-width="1"/>';

    var innerGap = innerGapCfg;
    var nBars = 3;
    var barH = Math.max(10, (rowBand - innerGap * (nBars + 1)) / nBars);
    var fills = [CHART.barP1, CHART.barP2, CHART.barDiff];
    var baseValForBar = minVal < 0 && maxVal > 0 ? 0 : minVal;

    for (var ri = 0; ri < rows.length; ri++) {
      var yRowTop = plotTop + ri * rowBand;
      svg +=
        '<text x="' +
        (pad.left + labelColW - 10) +
        '" y="' +
        (yRowTop + rowBand / 2 + fs * 0.35) +
        '" text-anchor="end" font-size="' +
        fs +
        '" fill="' +
        axisClr +
        '">' +
        escape_html(rows[ri].label) +
        "</text>";

      var vals = [rows[ri].left, rows[ri].right, rows[ri].diff];
      for (var k = 0; k < 3; k++) {
        var yb = yRowTop + innerGap + k * (barH + innerGap);
        var hg = hBarGeom(vals[k]);
        svg +=
          '<rect x="' +
          hg.x +
          '" y="' +
          yb +
          '" width="' +
          hg.w +
          '" height="' +
          barH +
          '" fill="' +
          fills[k] +
          '" stroke="' +
          barStroke +
          '" stroke-width="0.65" shape-rendering="crispEdges"/>';
        var midX = hg.x + hg.w / 2;
        var inside = hg.w > fs * 3.2;
        var tx;
        var tAnchor;
        var tFill;
        var tWeight;
        if (inside) {
          tx = midX;
          tAnchor = "middle";
          tFill = "#fff";
          tWeight = "600";
        } else if (Number(vals[k]) >= baseValForBar) {
          tx = hg.x + hg.w + 5;
          tAnchor = "start";
          tFill = axisClr;
          tWeight = "400";
        } else {
          tx = hg.x - 5;
          tAnchor = "end";
          tFill = axisClr;
          tWeight = "400";
        }
        svg +=
          '<text x="' +
          tx +
          '" y="' +
          (yb + barH * 0.72) +
          '" text-anchor="' +
          tAnchor +
          '" font-size="' +
          fsSmall +
          '" fill="' +
          tFill +
          '" font-weight="' +
          tWeight +
          '">' +
          format_num(vals[k]) +
          "</text>";
      }
    }

    svg +=
      '<text x="' +
      (plotLeft + plotW / 2) +
      '" y="22" text-anchor="middle" font-size="' +
      (fs + 1) +
      '" font-weight="600" fill="' +
      axisClr +
      '">Mode: Left / Right / Difference</text>';
    svg +=
      '<text x="' +
      (plotLeft + plotW / 2) +
      '" y="' +
      (ph - 2) +
      '" text-anchor="middle" font-size="' +
      Math.max(9, fs - 2) +
      '" fill="' +
      axisClr +
      '">Value</text>';
    svg += "</g></svg>";
    return svg;
  }

  function render_mode(frm) {
    var m = safe_json(frm.doc.mode_values_json, null);
    if (!m || typeof m !== "object") {
      return '<div class="pts3-result-section"><h4>Mode Results</h4><p class="pts3-result-no-data">No mode data</p></div>';
    }
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var html = '<div class="pts3-result-section"><h4>Mode Results</h4>';
    if (Object.keys(m).length) {
      var legendPx =
        MODE_HBAR.legendFontPx != null && MODE_HBAR.legendFontPx > 0
          ? MODE_HBAR.legendFontPx
          : MODE_CHART.fontSize != null
            ? MODE_CHART.fontSize
            : pts3_axis_font();
      html +=
        '<div class="pts3-mode-legend" style="font-size:' +
        legendPx +
        "px;font-family:" +
        PTS3_SANS_FONT_STACK_CSS +
        ';"><span style="color:' +
        CHART.barP1 +
        '">■</span> Left &nbsp; <span style="color:' +
        CHART.barP2 +
        '">■</span> Right &nbsp; <span style="color:' +
        CHART.barDiff +
        '">■</span> Difference</div>';
      html += '<div class="pts3-mode-layout">';
      html += '<div class="pts3-mode-chart pts3-mode-chart-only"><div class="pts3-chart-wrap">' + render_mode_chart_svg(m) + "</div></div>";
      html += "</div>";
    }
    html += "</div>";
    return html;
  }

  function render_lrd_summary(frm) {
    var t = safe_json(frm.doc.left_right_diff_summary_json, null);
    if (!t || typeof t !== "object") {
      return '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4><p class="pts3-result-no-data">No data</p></div>';
    }
    var meta = t.metadata || {};
    var left = t.left || {};
    var right = t.right || {};
    var diff = t.diff || {};
    var keys = Object.keys(left).concat(Object.keys(right)).concat(Object.keys(diff));
    keys = keys.filter(function (k, i, a) { return a.indexOf(k) === i; }).sort();
    var html = '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4>';
    if (Object.keys(meta).length) {
      html += "<p><strong>Metadata:</strong> " + escape_html(JSON.stringify(meta)) + "</p>";
    }
    html += "<table class=\"pts3-result-table\"><thead><tr><th>Key</th><th>Left</th><th>Right</th><th>Diff</th></tr></thead><tbody>";
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      html +=
        "<tr><td>" +
        escape_html(k) +
        "</td><td>" +
        escape_html(left[k] != null ? left[k] : "") +
        "</td><td>" +
        escape_html(right[k] != null ? right[k] : "") +
        "</td>" +
        pts3_diff_td_open(diff[k]) +
        escape_html(diff[k] != null ? diff[k] : "") +
        "</td></tr>";
    }
    html += "</tbody></table></div>";
    return html;
  }

  function render_artifacts(frm) {
    var ap = frm.doc.artifact_paths || "";
    var html = '<div class="pts3-result-section"><h4>Artifacts</h4>';
    var obj = null;
    if (typeof ap === "string" && ap.trim()) {
      try {
        obj = JSON.parse(ap);
      } catch (e) {
        obj = null;
      }
    }
    if (obj && typeof obj === "object") {
      var pc = obj.pc_name || "";
      var excel = obj.excel_path || "";
      var log = obj.log_path || "";
      var plot = obj.plot_path || "";
      html += "<div class=\"pts3-result-artifact\"><strong>PC:</strong> " + escape_html(pc || "(not set)") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Excel:</strong> " + escape_html(excel || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Log:</strong> " + escape_html(log || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Plot:</strong> " + escape_html(plot || "-") + "</div>";
    } else if (ap && typeof ap === "string") {
      html += "<div class=\"pts3-result-artifact\"><strong>Legacy path:</strong> " + escape_html(ap) + "</div>";
    } else {
      html += "<p class=\"pts3-result-no-data\">No artifact paths</p>";
    }
    html += "</div>";
    return html;
  }

  function load_html2canvas(done) {
    if (typeof window.html2canvas === "function") {
      done();
      return;
    }
    if (window.__pts3_h2c_loading) {
      window.__pts3_h2c_queue = window.__pts3_h2c_queue || [];
      window.__pts3_h2c_queue.push(done);
      return;
    }
    window.__pts3_h2c_loading = true;
    var sc = document.createElement("script");
    sc.src = HTML2CANVAS_CDN;
    sc.crossOrigin = "anonymous";
    sc.onload = function () {
      window.__pts3_h2c_loading = false;
      done();
      var q = window.__pts3_h2c_queue || [];
      window.__pts3_h2c_queue = [];
      for (var qi = 0; qi < q.length; qi++) {
        q[qi]();
      }
    };
    sc.onerror = function () {
      window.__pts3_h2c_loading = false;
      frappe.msgprint(__("Could not load html2canvas (CDN blocked or offline)."));
    };
    document.head.appendChild(sc);
  }

  function bind_inspection_download(frm, $wrapper) {
    $wrapper.find(".pts3-download-inspection-png").off("click.pts3cap");
    $wrapper.find(".pts3-download-inspection-png").on("click.pts3cap", function () {
      var root = $wrapper.find(".pts3-inspection-capture-body")[0];
      if (!root) {
        frappe.msgprint(__("Nothing to capture."));
        return;
      }
      load_html2canvas(function () {
        frappe.show_alert({ message: __("Rendering PNG…"), indicator: "blue" });
        var bg = "#ffffff";
        try {
          var b = getComputedStyle(document.body);
          if (b && b.backgroundColor && b.backgroundColor !== "rgba(0, 0, 0, 0)" && b.backgroundColor !== "transparent") {
            bg = b.backgroundColor;
          }
        } catch (e0) {}
        window
          .html2canvas(root, {
            scale: INSPECTION_PNG_SCALE,
            useCORS: true,
            allowTaint: true,
            logging: false,
            backgroundColor: bg,
            ignoreElements: function (el) {
              return el.classList && el.classList.contains("pts3-inspection-toolbar");
            },
          })
          .then(function (canvas) {
            canvas.toBlob(
              function (blob) {
                if (!blob) {
                  frappe.msgprint(__("PNG export failed."));
                  return;
                }
                var name = (frm.doc.name || "PTS3_Result").replace(/[^\w.-]+/g, "_");
                var a = document.createElement("a");
                a.href = URL.createObjectURL(blob);
                a.download = name + "_inspection.png";
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(a.href);
                frappe.show_alert({ message: __("Download started"), indicator: "green" });
              },
              "image/png",
              0.98
            );
          })
          .catch(function (err) {
            frappe.msgprint(__("Capture error: ") + (err && err.message ? err.message : String(err)));
          });
      });
    });
  }

  function render_inspection(frm) {
    if (!frm.doc.name) return "";
    var inner =
      '<div class="pts3-summary-mode-row">' +
      render_summary(frm) +
      render_mode(frm) +
      "</div>" +
      render_step_sweep(frm);
    if (SHOW_LEFT_RIGHT_DIFF_SUMMARY_SECTION) {
      inner += render_lrd_summary(frm);
    }
    inner += render_artifacts(frm);
    return (
      '<div class="pts3-inspection-capture-root" style="width:100%;max-width:100%;box-sizing:border-box;margin:0;display:block;">' +
      '<table role="presentation" style="width:100%;max-width:100%;border-collapse:collapse;margin:0;padding:0;border:none;"><tr><td style="padding:0;border:none;vertical-align:top;width:100%;">' +
      '<div class="pts3-inspection-toolbar">' +
      '<button type="button" class="btn btn-default btn-sm pts3-download-inspection-png">' +
      __("Download inspection as PNG") +
      "</button>" +
      '<span class="text-muted small">' +
      __("Uses html2canvas from CDN; scale ") +
      String(INSPECTION_PNG_SCALE) +
      "×</span></div>" +
      '<div class="pts3-inspection-capture-body" style="width:100%;max-width:100%;box-sizing:border-box;">' +
      inner +
      "</div></td></tr></table></div>"
    );
  }

  function setup_sweep_hover() {
    $(document).off("mousemove.pts3sweep mouseleave.pts3sweep");
    $(document).on("mousemove.pts3sweep", ".pts3-sweep-chart-container", function (e) {
      var $c = $(this);
      var dataStr = $c.attr("data-sweep");
      if (!dataStr) return;
      var data;
      try {
        data = JSON.parse(dataStr);
      } catch (err) {
        return;
      }
      var coords = data.coords;
      var freqs = data.freqs || [];
      var left = data.left || [];
      var right = data.right || [];
      var diff = data.diff || [];
      if (!coords || !freqs.length) return;
      var svg = $c.find("svg")[0];
      if (!svg) return;
      var rect = svg.getBoundingClientRect();
      var vx = ((e.clientX - rect.left) / rect.width) * coords.pw;
      var vy = ((e.clientY - rect.top) / rect.height) * coords.ph;
      if (vx < coords.gx || vx > coords.gx + coords.gw || vy < coords.gy || vy > coords.gy + coords.gh) {
        $c.find(".pts3-sweep-tooltip").removeClass("visible");
        return;
      }
      var freq = coords.freqMin + ((vx - coords.gx) / coords.gw) * coords.freqRange;
      var idx = Math.round(((vx - coords.gx) / coords.gw) * (freqs.length - 1));
      idx = Math.max(0, Math.min(idx, freqs.length - 1));
      var f = Number(freqs[idx]);
      var l = left[idx] != null ? format_num(left[idx]) : "-";
      var r = right[idx] != null ? format_num(right[idx]) : "-";
      var d = diff[idx] != null ? format_num(diff[idx]) : "-";
      var $tip = $c.find(".pts3-sweep-tooltip");
      var cRect = $c[0].getBoundingClientRect();
      $tip.html("<strong>" + f + " Hz</strong><br>Left: " + l + " &nbsp; Right: " + r + " &nbsp; Diff: " + d);
      $tip.css({ left: (e.clientX - cRect.left + 12) + "px", top: (e.clientY - cRect.top + 12) + "px" });
      $tip.addClass("visible");
    });
    $(document).on("mouseleave.pts3sweep", ".pts3-sweep-chart-container", function () {
      $(this).find(".pts3-sweep-tooltip").removeClass("visible");
    });
  }

  /** Same as Desk → user menu → Toggle Full Width (ON). Persists in localStorage like the built-in toggle. */
  function pts3_ensure_desk_full_width() {
    if (!PTS3_ENABLE_DESK_FULL_WIDTH_ON_LOAD) return;
    try {
      if (typeof localStorage !== "undefined") {
        localStorage.setItem("container_fullwidth", "true");
      }
      if (typeof frappe !== "undefined" && frappe.ui && frappe.ui.toolbar && typeof frappe.ui.toolbar.set_fullwidth_if_enabled === "function") {
        frappe.ui.toolbar.set_fullwidth_if_enabled();
      } else if (typeof $ !== "undefined" && $(document.body).length) {
        $(document.body).addClass("full-width");
      }
      if (typeof $ !== "undefined") {
        $(document.body).trigger("toggleFullWidth");
      }
    } catch (e) {}
  }

  frappe.ui.form.on("PTS3 Result", {
    onload: function () {
      setTimeout(pts3_ensure_desk_full_width, 0);
    },
    refresh: function (frm) {
      pts3_ensure_desk_full_width();
      pts3Dbg(
        "PTS3 Result refresh",
        frm.doc.name,
        "run_id=" + (frm.doc.run_id || ""),
        "op=" + (frm.doc.operation || ""),
        "final_graph_json len=" + String(frm.doc.final_graph_json || "").length,
        "left_right_diff_summary_json len=" + String(frm.doc.left_right_diff_summary_json || "").length,
        "mode_values_json len=" + String(frm.doc.mode_values_json || "").length
      );
      var field = frm.get_field("result_inspection");
      if (field && field.$wrapper) {
        field.$wrapper.html(render_inspection(frm));
        setup_sweep_hover();
        bind_inspection_download(frm, field.$wrapper);
      }
    }
  });
})();

// ============================================================
// PTS3 Result - Client Script (Visual Inspection)
// DocType: PTS3 Result
// Renders: Summary, Step Sweep (chart + table), Mode (chart + table), Left/Right/Diff, Artifacts
// Uses final_graph_json, mode_values_json, left_right_diff_summary_json, artifact_paths
// ============================================================

(function () {
  // Chart styling - theme-aware (light/dark mode compatible)
  var CHART = {
    width: 1000,
    height: 500,
    padding: { top: 20, right: 20, bottom: 40, left: 65 },
    fontSize: 10,        // Axis and label font size (e.g. 8, 10, 12)
    lineLeft: "#E53935",   // Red for Left
    lineRight: "#2196F3",  // Blue for Right
    lineDiff: "#4CAF50",   // Green for Diff
    barP1: "#E53935",      // Red for P1 (Left)
    barP2: "#2196F3",      // Blue for P2 (Right)
    barDiff: "#4CAF50",    // Green for Diff
    axisColor: "var(--text-muted, #6c7680)",
    gridColor: "var(--border-color, #d1d8dd)"
  };

  // Step Sweep chart - manual axis adjustments (edit these values)
  var SWEEP_CHART = {
    yMin: 1500,      // e.g. 1500 - set to fix Y-axis minimum (null = auto from data)
    yMax: 2500,      // e.g. 2500 - set to fix Y-axis maximum (null = auto from data)
    xTickHz: 2,      // X-axis tick interval in Hz (e.g. 2 = every 2Hz: 40,42,44...; 10 = 40,50,60...)
    lineWidth: 2,    // Line thickness for Left/Right (e.g. 1, 2, 3)
    diffLineWidth: 1.5,  // Line thickness for Diff (null = uses lineWidth)
    fontSize: null   // Override font size for this chart (null = use CHART.fontSize)
  };

  // Mode chart - manual axis adjustments (edit these values)
  var MODE_CHART = {
    yMin: null,    // e.g. 0 - set to fix Y-axis minimum (null = auto from data)
    yMax: null,    // e.g. 150 - set to fix Y-axis maximum (null = auto from data)
    fontSize: null // Override font size for this chart (null = use CHART.fontSize)
  };

  if (document.getElementById("pts3-result-style") == null) {
    var style = document.createElement("style");
    style.id = "pts3-result-style";
    style.textContent = ".pts3-result-section{margin:1rem 0;padding:0.75rem;border:1px solid var(--border-color,#d1d8dd);border-radius:4px;}.pts3-result-section h4{margin:0 0 0.5rem 0;font-size:1rem;color:var(--text-color,#36414c);}.pts3-result-table{font-size:0.85em;border-collapse:collapse;}.pts3-result-table th,.pts3-result-table td{border:1px solid var(--border-color,#d1d8dd);padding:4px 8px;text-align:left;color:var(--text-color,#36414c);}.pts3-result-table th{background:var(--control-bg,#f5f7fa);}.pts3-result-artifact{margin:0.25rem 0;font-size:0.9em;}.pts3-result-no-data{color:var(--text-muted,#8d99a6);font-style:italic;}.pts3-result-pass{color:#27ae60;}.pts3-result-fail{color:#e74c3c;}.pts3-chart-wrap{margin:0.5rem 0;overflow-x:auto;}.pts3-mode-layout{display:flex;flex-wrap:wrap;gap:1rem;align-items:stretch;}.pts3-mode-legend{width:100%;margin-bottom:0.25rem;}.pts3-mode-table{flex:0 0 auto;min-width:180px;}.pts3-mode-chart{flex:1 1 350px;min-width:320px;}.pts3-sweep-chart-container{position:relative;display:block;cursor:crosshair;min-width:400px;min-height:260px;}.pts3-sweep-tooltip{position:absolute;display:none;background:var(--gray-900,#36414c);color:var(--gray-100,#fff);padding:6px 10px;border-radius:4px;font-size:11px;font-family:monospace;white-space:nowrap;pointer-events:none;z-index:1000;box-shadow:0 2px 8px rgba(0,0,0,0.2);}.pts3-sweep-tooltip.visible{display:block;}";
    document.head.appendChild(style);
  }

  /** Accepts JSON string or already-parsed object (some Frappe/API paths deserialize Code fields). */
  function safe_json(val, fallback) {
    if (val == null || val === "") return fallback || {};
    if (typeof val === "object" && val !== null && !Array.isArray(val)) {
      return val;
    }
    if (typeof val === "string") {
      try {
        var o = JSON.parse(val);
        return o && typeof o === "object" && !Array.isArray(o) ? o : (fallback || {});
      } catch (e) {
        return fallback || {};
      }
    }
    return fallback || {};
  }

  function escape_html(s) {
    if (s == null || s === undefined) return "";
    var t = String(s);
    return t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function render_summary(frm) {
    var d = frm.doc;
    var html = '<div class="pts3-result-section"><h4>Summary</h4><table class="pts3-result-table"><tbody>';
    html += "<tr><th>PCB Serial No</th><td>" + escape_html(d.pcb_serial_no || "") + "</td></tr>";
    html += "<tr><th>Run ID</th><td>" + escape_html(d.run_id || "") + "</td></tr>";
    html += "<tr><th>Operation</th><td>" + escape_html(d.operation || "") + "</td></tr>";
    html += "<tr><th>Datetime</th><td>" + escape_html(d.datetime || "") + "</td></tr>";
    var pf = (d.pass_fail || "").trim();
    var pfClass = pf === "Pass" ? "pts3-result-pass" : pf === "Fail" ? "pts3-result-fail" : "";
    html += "<tr><th>Pass/Fail</th><td class=\"" + pfClass + "\">" + escape_html(pf || "-") + "</td></tr>";
    html += "<tr><th>Dominant Channel</th><td>" + escape_html(d.dominant_channel || "") + "</td></tr>";
    html += "<tr><th>Max Value</th><td>" + escape_html(d.max_value != null ? d.max_value : "") + "</td></tr>";
    html += "</tbody></table></div>";
    return html;
  }

  function format_num(v) {
    if (v == null || isNaN(v)) return "";
    var n = Number(v);
    return n % 1 === 0 ? String(n) : n.toFixed(2);
  }

  function render_sweep_chart_svg(freqs, left, right, diff) {
    if (!freqs || freqs.length < 2) return { svg: "", coords: null };
    var pw = CHART.width;
    var ph = CHART.height;
    var pad = CHART.padding;
    var gx = pad.left;
    var gy = pad.top;
    var gw = pw - pad.left - pad.right;
    var gh = ph - pad.top - pad.bottom;
    var axisClr = CHART.axisColor;
    var gridClr = CHART.gridColor;
    var fs = SWEEP_CHART.fontSize != null ? SWEEP_CHART.fontSize : (CHART.fontSize || 10);

    var allVals = [];
    for (var i = 0; i < left.length; i++) { if (left[i] != null) allVals.push(Number(left[i])); }
    for (var j = 0; j < right.length; j++) { if (right[j] != null) allVals.push(Number(right[j])); }
    for (var k = 0; k < diff.length; k++) { if (diff[k] != null) allVals.push(Number(diff[k])); }
    var vMin = SWEEP_CHART.yMin != null ? Number(SWEEP_CHART.yMin) : (allVals.length ? Math.min.apply(null, allVals) : 0);
    var vMax = SWEEP_CHART.yMax != null ? Number(SWEEP_CHART.yMax) : (allVals.length ? Math.max.apply(null, allVals) : 1);
    var vRange = vMax - vMin || 1;

    function x(i) { return gx + (i / Math.max(freqs.length - 1, 1)) * gw; }
    function y(v) { return gy + gh - ((Number(v) - vMin) / vRange) * gh; }

    function path(arr) {
      var pts = [];
      for (var i = 0; i < arr.length; i++) {
        if (arr[i] != null && !isNaN(Number(arr[i]))) {
          pts.push(x(i) + "," + y(arr[i]));
        }
      }
      return pts.length ? "M" + pts.join(" L") : "";
    }

    var pLeft = path(left);
    var pRight = path(right);
    var pDiff = path(diff);

    var freqMin = Number(freqs[0]) || 0;
    var freqMax = Number(freqs[freqs.length - 1]) || 1;
    var freqRange = freqMax - freqMin || 1;
    var xTickHz = SWEEP_CHART.xTickHz > 0 ? SWEEP_CHART.xTickHz : 2;
    function xFromFreq(f) { return gx + ((Number(f) - freqMin) / freqRange) * gw; }

    var svg = '<svg class="pts3-chart-svg" width="' + pw + '" height="' + ph + '" viewBox="0 0 ' + pw + ' ' + ph + '" preserveAspectRatio="xMidYMid meet" style="max-width:100%;height:auto;display:block;"><g>';
    var yticks = 5;
    for (var tickFreq = freqMin; tickFreq <= freqMax; tickFreq += xTickHz) {
      var xx = xFromFreq(tickFreq);
      if (xx < gx - 1 || xx > gx + gw + 1) continue;
      svg += '<line x1="' + xx + '" y1="' + (gy + gh) + '" x2="' + xx + '" y2="' + gy + '" stroke="' + gridClr + '" stroke-width="0.5" opacity="0.5"/>';
      if (tickFreq > freqMin && tickFreq < freqMax) svg += '<line x1="' + xx + '" y1="' + (gy + gh) + '" x2="' + xx + '" y2="' + (gy + gh + 4) + '" stroke="' + axisClr + '" stroke-width="1"/>';
      svg += '<text x="' + xx + '" y="' + (ph - 2) + '" text-anchor="middle" font-size="' + fs + '" fill="' + axisClr + '">' + tickFreq + '</text>';
    }
    for (var yi = 0; yi <= yticks; yi++) {
      var yy = gy + gh - (yi / yticks) * gh;
      svg += '<line x1="' + gx + '" y1="' + yy + '" x2="' + (gx + gw) + '" y2="' + yy + '" stroke="' + gridClr + '" stroke-width="0.5" opacity="0.5"/>';
      if (yi > 0 && yi < yticks) svg += '<line x1="' + (gx - 4) + '" y1="' + yy + '" x2="' + gx + '" y2="' + yy + '" stroke="' + axisClr + '" stroke-width="1"/>';
      var v = vMin + (yi / yticks) * vRange;
      svg += '<text x="' + (gx - 6) + '" y="' + (yy + 3) + '" text-anchor="end" font-size="' + fs + '" fill="' + axisClr + '">' + format_num(v) + '</text>';
    }
    svg += '<line x1="' + gx + '" y1="' + (gy + gh) + '" x2="' + (gx + gw) + '" y2="' + (gy + gh) + '" stroke="' + axisClr + '" stroke-width="1"/>';
    svg += '<line x1="' + gx + '" y1="' + gy + '" x2="' + gx + '" y2="' + (gy + gh) + '" stroke="' + axisClr + '" stroke-width="1"/>';
    var lw = SWEEP_CHART.lineWidth > 0 ? SWEEP_CHART.lineWidth : 2;
    var dlw = SWEEP_CHART.diffLineWidth != null ? SWEEP_CHART.diffLineWidth : lw;
    if (pLeft) svg += '<path d="' + pLeft + '" fill="none" stroke="' + CHART.lineLeft + '" stroke-width="' + lw + '"/>';
    if (pRight) svg += '<path d="' + pRight + '" fill="none" stroke="' + CHART.lineRight + '" stroke-width="' + lw + '"/>';
    if (pDiff) svg += '<path d="' + pDiff + '" fill="none" stroke="' + CHART.lineDiff + '" stroke-width="' + dlw + '" stroke-dasharray="4,2"/>';
    svg += '</g></svg>';
    var coords = { freqMin: freqMin, freqMax: freqMax, freqRange: freqRange, vMin: vMin, vMax: vMax, vRange: vRange, gx: gx, gy: gy, gw: gw, gh: gh, pw: pw, ph: ph };
    return { svg: svg, coords: coords };
  }

  function build_sweep_from_lrd(t) {
    if (!t || typeof t !== "object") return null;
    var left = t.left || {};
    var right = t.right || {};
    var diff = t.diff || {};
    var keys = Object.keys(left).concat(Object.keys(right)).concat(Object.keys(diff));
    keys = keys.filter(function (k, i, a) { return a.indexOf(k) === i; }).sort(function (a, b) {
      var na = parseInt(String(a).replace(/[^0-9]/g, ""), 10) || 0;
      var nb = parseInt(String(b).replace(/[^0-9]/g, ""), 10) || 0;
      return na - nb;
    });
    if (keys.length < 2) return null;
    var freqs = [];
    var leftArr = [];
    var rightArr = [];
    var diffArr = [];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      var hz = parseInt(String(k).replace(/[^0-9]/g, ""), 10);
      if (!isNaN(hz)) {
        freqs.push(hz);
        leftArr.push(left[k] != null ? left[k] : null);
        rightArr.push(right[k] != null ? right[k] : null);
        diffArr.push(diff[k] != null ? diff[k] : null);
      }
    }
    return freqs.length >= 2 ? { freqs: freqs, left: leftArr, right: rightArr, diff: diffArr } : null;
  }

  function render_step_sweep(frm) {
    var g = safe_json(frm.doc.final_graph_json, null);
    var isSweep = g && (g.type === "sweep" || g.type === "step_sweep") && (g.freqs || []).length >= 2;
    if (!isSweep) {
      var lrd = safe_json(frm.doc.left_right_diff_summary_json, null);
      g = build_sweep_from_lrd(lrd);
    }
    if (!g || !g.freqs || g.freqs.length < 2) {
      return '<div class="pts3-result-section"><h4>Step Sweep</h4><p class="pts3-result-no-data">No sweep data</p></div>';
    }
    var freqs = g.freqs || [];
    var left = g.left || [];
    var right = g.right || [];
    var diff = g.diff || [];
    var html = '<div class="pts3-result-section"><h4>Step Sweep</h4>';
    if (freqs.length >= 2) {
      var chartResult = render_sweep_chart_svg(freqs, left, right, diff);
      var sweepData = JSON.stringify({ freqs: freqs, left: left, right: right, diff: diff, coords: chartResult.coords });
      html += '<div class="pts3-chart-wrap"><p style="font-size:' + (SWEEP_CHART.fontSize != null ? SWEEP_CHART.fontSize : CHART.fontSize || 10) + 'px;margin:0 0 4px 0;"><span style="color:' + CHART.lineLeft + '">—</span> Left &nbsp; <span style="color:' + CHART.lineRight + '">—</span> Right &nbsp; <span style="color:' + CHART.lineDiff + '">- -</span> Diff</p>';
      html += '<div class="pts3-sweep-chart-container" data-sweep="' + escape_html(sweepData) + '"><div class="pts3-sweep-tooltip" id="pts3-sweep-tooltip"></div>' + chartResult.svg + '</div></div>';
    }
    html += '<table class="pts3-result-table"><thead><tr><th>Channel</th>';
    for (var h = 0; h < freqs.length; h++) {
      html += '<th>' + escape_html(freqs[h]) + 'hz</th>';
    }
    html += '</tr></thead><tbody>';
    html += '<tr><td>Left</td>';
    for (var a = 0; a < freqs.length; a++) {
      html += '<td>' + escape_html(format_num(left[a])) + '</td>';
    }
    html += '</tr><tr><td>Right</td>';
    for (var b = 0; b < freqs.length; b++) {
      html += '<td>' + escape_html(format_num(right[b])) + '</td>';
    }
    html += '</tr><tr><td>Diff</td>';
    for (var c = 0; c < freqs.length; c++) {
      html += '<td>' + escape_html(format_num(diff[c])) + '</td>';
    }
    html += '</tr></tbody></table></div>';
    return html;
  }

  function get_mode_value(m, key) {
    if (m[key]) return m[key];
    var lower = key.toLowerCase();
    if (m[lower]) return m[lower];
    return null;
  }

  function render_mode_chart_svg(modeData) {
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var rows = [];
    for (var i = 0; i < order.length; i++) {
      var v = get_mode_value(modeData, order[i]);
      if (v && typeof v === "object") {
        rows.push({
          label: order[i],
          p1: v.p1 != null ? Number(v.p1) : 0,
          p2: v.p2 != null ? Number(v.p2) : 0,
          diff: v.diff != null ? Number(v.diff) : 0
        });
      }
    }
    if (rows.length === 0) return "";

    var pw = CHART.width;
    var ph = 220;
    var pad = { top: 25, right: 20, bottom: 40, left: 52 };
    var gw = pw - pad.left - pad.right;
    var gh = ph - pad.top - pad.bottom;

    var maxVal = 0;
    for (var r = 0; r < rows.length; r++) {
      if (rows[r].p1 > maxVal) maxVal = rows[r].p1;
      if (rows[r].p2 > maxVal) maxVal = rows[r].p2;
      if (rows[r].diff > maxVal) maxVal = rows[r].diff;
    }
    maxVal = MODE_CHART.yMax != null ? Number(MODE_CHART.yMax) : (maxVal || 1);
    var minVal = MODE_CHART.yMin != null ? Number(MODE_CHART.yMin) : 0;
    var valRange = Math.max(maxVal - minVal, 0.001);

    var groupW = gw / Math.max(rows.length, 1);
    var barW = groupW / 5;
    var gap = barW * 0.3;
    var totalBars = 3 * barW + 2 * gap;

    function barX(idx, offset) {
      var groupCenter = pad.left + (idx + 0.5) * groupW;
      var startX = groupCenter - totalBars / 2;
      return startX + offset * (barW + gap);
    }
    function barH(v) {
      var val = Number(v) || 0;
      return Math.max(0, ((val - minVal) / valRange) * gh);
    }

    var axisClr = CHART.axisColor;
    var gridClr = CHART.gridColor;
    var fs = MODE_CHART.fontSize != null ? MODE_CHART.fontSize : (CHART.fontSize || 10);
    var fsSmall = Math.max(6, fs - 2);
    var svg = '<svg class="pts3-chart-svg" viewBox="0 0 ' + pw + ' ' + ph + '" preserveAspectRatio="xMidYMid meet" style="max-width:100%;height:auto;"><g>';
    for (var yi = 0; yi <= 4; yi++) {
      var yy = pad.top + gh - (yi / 4) * gh;
      svg += '<line x1="' + pad.left + '" y1="' + yy + '" x2="' + (pw - pad.right) + '" y2="' + yy + '" stroke="' + gridClr + '" stroke-width="0.5" opacity="0.5"/>';
      var yVal = minVal + (yi / 4) * valRange;
      svg += '<line x1="' + (pad.left - 4) + '" y1="' + yy + '" x2="' + pad.left + '" y2="' + yy + '" stroke="' + axisClr + '" stroke-width="1"/>';
      svg += '<text x="' + (pad.left - 6) + '" y="' + (yy + 3) + '" text-anchor="end" font-size="' + fs + '" fill="' + axisClr + '">' + format_num(yVal) + '</text>';
    }
    svg += '<line x1="' + pad.left + '" y1="' + (pad.top + gh) + '" x2="' + (pw - pad.right) + '" y2="' + (pad.top + gh) + '" stroke="' + axisClr + '" stroke-width="1"/>';
    for (var i = 0; i < rows.length; i++) {
      var x0 = barX(i, 0);
      var x1 = barX(i, 1);
      var x2 = barX(i, 2);
      var baseY = pad.top + gh;
      var h1 = barH(rows[i].p1);
      var h2 = barH(rows[i].p2);
      var hd = barH(Math.abs(rows[i].diff));
      var cx0 = x0 + barW / 2;
      var cx1 = x1 + barW / 2;
      var cx2 = x2 + barW / 2;
      svg += '<rect x="' + x0 + '" y="' + (baseY - h1) + '" width="' + barW + '" height="' + h1 + '" fill="' + CHART.barP1 + '"/>';
      svg += '<rect x="' + x1 + '" y="' + (baseY - h2) + '" width="' + barW + '" height="' + h2 + '" fill="' + CHART.barP2 + '"/>';
      svg += '<rect x="' + x2 + '" y="' + (baseY - hd) + '" width="' + barW + '" height="' + hd + '" fill="' + CHART.barDiff + '"/>';
      if (rows[i].p1 > 0) svg += '<text x="' + cx0 + '" y="' + (baseY - h1 - 3) + '" text-anchor="middle" font-size="' + fsSmall + '" fill="' + axisClr + '">' + format_num(rows[i].p1) + '</text>';
      if (rows[i].p2 > 0) svg += '<text x="' + cx1 + '" y="' + (baseY - h2 - 3) + '" text-anchor="middle" font-size="' + fsSmall + '" fill="' + axisClr + '">' + format_num(rows[i].p2) + '</text>';
      if (rows[i].diff !== 0) svg += '<text x="' + cx2 + '" y="' + (baseY - hd - 3) + '" text-anchor="middle" font-size="' + fsSmall + '" fill="' + axisClr + '">' + format_num(rows[i].diff) + '</text>';
      svg += '<text x="' + (pad.left + i * groupW + groupW / 2) + '" y="' + (ph - 8) + '" text-anchor="middle" font-size="' + fs + '" fill="' + axisClr + '">' + escape_html(rows[i].label) + '</text>';
    }
    svg += '</g></svg>';
    return svg;
  }

  function render_mode(frm) {
    var m = safe_json(frm.doc.mode_values_json, null);
    if (!m || typeof m !== "object") {
      return '<div class="pts3-result-section"><h4>Mode Results</h4><p class="pts3-result-no-data">No mode data</p></div>';
    }
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var html = '<div class="pts3-result-section"><h4>Mode Results</h4>';
    if (Object.keys(m).length) {
      html += '<div class="pts3-mode-legend" style="font-size:' + (MODE_CHART.fontSize != null ? MODE_CHART.fontSize : CHART.fontSize || 10) + 'px;"><span style="color:' + CHART.barP1 + '">■</span> P1 &nbsp; <span style="color:' + CHART.barP2 + '">■</span> P2 &nbsp; <span style="color:' + CHART.barDiff + '">■</span> Diff</div>';
      html += '<div class="pts3-mode-layout">';
      html += '<div class="pts3-mode-table"><table class="pts3-result-table"><thead><tr><th>Mode</th><th>P1</th><th>P2</th><th>Diff</th></tr></thead><tbody>';
      for (var i = 0; i < order.length; i++) {
        var k = order[i];
        var v = get_mode_value(m, k);
        if (v && typeof v === "object") {
          html += "<tr><td>" + escape_html(k) + "</td><td>" + escape_html(v.p1 != null ? v.p1 : "") + "</td><td>" + escape_html(v.p2 != null ? v.p2 : "") + "</td><td>" + escape_html(v.diff != null ? v.diff : "") + "</td></tr>";
        }
      }
      html += "</tbody></table></div>";
      html += '<div class="pts3-mode-chart"><div class="pts3-chart-wrap">' + render_mode_chart_svg(m) + '</div></div>';
      html += '</div>';
    }
    html += "</div>";
    return html;
  }

  function render_lrd_summary(frm) {
    var t = safe_json(frm.doc.left_right_diff_summary_json, null);
    if (!t || typeof t !== "object") {
      return '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4><p class="pts3-result-no-data">No data</p></div>';
    }
    var meta = t.metadata || {};
    var left = t.left || {};
    var right = t.right || {};
    var diff = t.diff || {};
    var keys = Object.keys(left).concat(Object.keys(right)).concat(Object.keys(diff));
    keys = keys.filter(function (k, i, a) { return a.indexOf(k) === i; }).sort();
    var html = '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4>';
    if (Object.keys(meta).length) {
      html += "<p><strong>Metadata:</strong> " + escape_html(JSON.stringify(meta)) + "</p>";
    }
    html += "<table class=\"pts3-result-table\"><thead><tr><th>Key</th><th>Left</th><th>Right</th><th>Diff</th></tr></thead><tbody>";
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      html += "<tr><td>" + escape_html(k) + "</td><td>" + escape_html(left[k] != null ? left[k] : "") + "</td><td>" + escape_html(right[k] != null ? right[k] : "") + "</td><td>" + escape_html(diff[k] != null ? diff[k] : "") + "</td></tr>";
    }
    html += "</tbody></table></div>";
    return html;
  }

  function render_artifacts(frm) {
    var ap = frm.doc.artifact_paths || "";
    var html = '<div class="pts3-result-section"><h4>Artifacts</h4>';
    var obj = null;
    if (typeof ap === "string" && ap.trim()) {
      try {
        obj = JSON.parse(ap);
      } catch (e) {
        obj = null;
      }
    }
    if (obj && typeof obj === "object") {
      var pc = obj.pc_name || "";
      var excel = obj.excel_path || "";
      var log = obj.log_path || "";
      var plot = obj.plot_path || "";
      html += "<div class=\"pts3-result-artifact\"><strong>PC:</strong> " + escape_html(pc || "(not set)") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Excel:</strong> " + escape_html(excel || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Log:</strong> " + escape_html(log || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Plot:</strong> " + escape_html(plot || "-") + "</div>";
    } else if (ap && typeof ap === "string") {
      html += "<div class=\"pts3-result-artifact\"><strong>Legacy path:</strong> " + escape_html(ap) + "</div>";
    } else {
      html += "<p class=\"pts3-result-no-data\">No artifact paths</p>";
    }
    html += "</div>";
    return html;
  }

  function render_inspection(frm) {
    if (!frm.doc.name) return "";
    var html = render_summary(frm) + render_step_sweep(frm) + render_mode(frm) + render_lrd_summary(frm) + render_artifacts(frm);
    return html;
  }

  function setup_sweep_hover() {
    $(document).off("mousemove.pts3sweep mouseleave.pts3sweep");
    $(document).on("mousemove.pts3sweep", ".pts3-sweep-chart-container", function (e) {
      var $c = $(this);
      var dataStr = $c.attr("data-sweep");
      if (!dataStr) return;
      var data;
      try {
        data = JSON.parse(dataStr);
      } catch (err) {
        return;
      }
      var coords = data.coords;
      var freqs = data.freqs || [];
      var left = data.left || [];
      var right = data.right || [];
      var diff = data.diff || [];
      if (!coords || !freqs.length) return;
      var svg = $c.find("svg")[0];
      if (!svg) return;
      var rect = svg.getBoundingClientRect();
      var vx = ((e.clientX - rect.left) / rect.width) * coords.pw;
      var vy = ((e.clientY - rect.top) / rect.height) * coords.ph;
      if (vx < coords.gx || vx > coords.gx + coords.gw || vy < coords.gy || vy > coords.gy + coords.gh) {
        $c.find(".pts3-sweep-tooltip").removeClass("visible");
        return;
      }
      var freq = coords.freqMin + ((vx - coords.gx) / coords.gw) * coords.freqRange;
      var idx = Math.round(((vx - coords.gx) / coords.gw) * (freqs.length - 1));
      idx = Math.max(0, Math.min(idx, freqs.length - 1));
      var f = Number(freqs[idx]);
      var l = left[idx] != null ? format_num(left[idx]) : "-";
      var r = right[idx] != null ? format_num(right[idx]) : "-";
      var d = diff[idx] != null ? format_num(diff[idx]) : "-";
      var $tip = $c.find(".pts3-sweep-tooltip");
      var cRect = $c[0].getBoundingClientRect();
      $tip.html("<strong>" + f + " Hz</strong><br>Left: " + l + " &nbsp; Right: " + r + " &nbsp; Diff: " + d);
      $tip.css({ left: (e.clientX - cRect.left + 12) + "px", top: (e.clientY - cRect.top + 12) + "px" });
      $tip.addClass("visible");
    });
    $(document).on("mouseleave.pts3sweep", ".pts3-sweep-chart-container", function () {
      $(this).find(".pts3-sweep-tooltip").removeClass("visible");
    });
  }

  frappe.ui.form.on("PTS3 Result", {
    refresh: function (frm) {
      var field = frm.get_field("result_inspection");
      if (field && field.$wrapper) {
        field.$wrapper.html(render_inspection(frm));
        setup_sweep_hover();
      }
    }
  });
})();
